<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { agrupadoras, cambiarEstadoTipoConceptoPlanilla, guardarTipoConceptoPlanilla, listarTiposConceptosPlanilla } from '../services/tiposConceptosPlanilla'
import type { TipoConceptoPlanilla, TipoConceptoPlanillaPayload } from '../interfaces/tiposConceptosPlanilla.interface'

type EstadoFiltro='todos'|'activo'|'inactivo'
const rows=ref<TipoConceptoPlanilla[]>([]),criterio=ref(''),estadoFiltro=ref<EstadoFiltro>('todos'),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null)
const form=reactive<TipoConceptoPlanillaPayload>({codigo:'',descripcion:'',agrupadora:null})
const message=(value:unknown)=>value instanceof Error?value.message:'No se pudo completar la operación.'
const filtered=computed(()=>{const search=criterio.value.trim().toLocaleLowerCase();return rows.value.filter(item=>(!search||`${item.codigo} ${item.descripcion} ${item.agrupadora??''}`.toLocaleLowerCase().includes(search))&&(estadoFiltro.value==='todos'||item.estado===(estadoFiltro.value==='activo')))})

async function load(){loading.value=true;error.value='';try{rows.value=await listarTiposConceptosPlanilla()}catch(value){error.value=message(value)}finally{loading.value=false}}
function open(item?:TipoConceptoPlanilla){editing.value=item?.id??null;Object.assign(form,item?{codigo:item.codigo,descripcion:item.descripcion,agrupadora:item.agrupadora}:{codigo:'',descripcion:'',agrupadora:null});error.value='';modal.value=true}
function validate(){if(form.codigo.trim().length<2)return 'El código debe tener al menos 2 caracteres.';if(form.codigo.trim().length>20)return 'El código admite como máximo 20 caracteres.';if(form.descripcion.trim().length<3)return 'La descripción debe tener al menos 3 caracteres.';if(form.descripcion.trim().length>200)return 'La descripción admite como máximo 200 caracteres.';return ''}
async function save(){const issue=validate();if(issue)return void(error.value=issue);saving.value=true;error.value='';try{await guardarTipoConceptoPlanilla(editing.value,{codigo:form.codigo.trim().toUpperCase(),descripcion:form.descripcion.trim().toUpperCase(),agrupadora:form.agrupadora});modal.value=false;success.value=`Tipo de concepto ${editing.value?'actualizado':'registrado'} correctamente.`;await load()}catch(value){error.value=message(value)}finally{saving.value=false}}
async function toggle(item:TipoConceptoPlanilla){const action=item.estado?'desactivar':'activar';if(!confirm(`¿Desea ${action} el tipo de concepto ${item.descripcion}?`))return;try{const result=await cambiarEstadoTipoConceptoPlanilla(item.id);item.estado=result.estado;success.value=result.message??`Tipo de concepto ${item.estado?'activado':'desactivado'} correctamente.`}catch(value){error.value=message(value)}}
function clearFilters(){criterio.value='';estadoFiltro.value='todos'}
onMounted(()=>load())
</script>

<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Recursos Humanos / Tipos de conceptos</nav><header class="hero"><div class="mark">TC</div><div><small>MIA · RECURSOS HUMANOS · MAESTROS</small><h1>Tipos de conceptos de planilla</h1><p>Clasificación y ubicación de los conceptos dentro de la boleta de pago.</p></div><strong>{{filtered.length}} de {{rows.length}}</strong><button @click="open()">+ Nuevo tipo</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><section class="filters"><label>Buscar por código o descripción<input v-model.trim="criterio" placeholder="Ej. INGRESO o DESCUENTO"></label><label>Estado<select v-model="estadoFiltro"><option value="todos">Todos</option><option value="activo">Activos</option><option value="inactivo">Inactivos</option></select></label><button type="button" class="soft" @click="clearFilters">Limpiar</button></section><section class="table-card"><header><div><small>ESTRUCTURA DE BOLETA</small><h2>Tipos de conceptos registrados</h2></div></header><div v-if="loading" class="empty">Consultando tipos de conceptos…</div><div v-else-if="!filtered.length" class="empty">No se encontraron tipos de conceptos.</div><div v-else class="scroll"><table><thead><tr><th>ID</th><th>Código</th><th>Descripción</th><th>Agrupadora de boleta</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in filtered" :key="item.id"><td>{{item.id}}</td><td><b>{{item.codigo}}</b></td><td>{{item.descripcion}}</td><td><span v-if="item.agrupadora" class="group" :data-group="item.agrupadora">{{item.agrupadora}}</span><span v-else>—</span></td><td><span :class="item.estado?'active':'inactive'">{{item.estado?'Activo':'Inactivo'}}</span></td><td class="actions"><button class="edit" @click="open(item)">Editar</button><button :class="item.estado?'disable':'enable'" @click="toggle(item)">{{item.estado?'Desactivar':'Activar'}}</button></td></tr></tbody></table></div></section><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div class="mark">TC</div><div><small>ESTRUCTURA DE BOLETA</small><h2>{{editing?'Editar':'Registrar'}} tipo de concepto</h2></div><button type="button" @click="modal=false">×</button></header><div class="grid"><label>Código *<input v-model="form.codigo" maxlength="20" @input="form.codigo=form.codigo.toUpperCase()"><small>Código único, máximo 20 caracteres.</small></label><label class="span2">Descripción *<input v-model="form.descripcion" maxlength="200" @input="form.descripcion=form.descripcion.toUpperCase()"></label><label class="span2">Agrupadora de boleta<select v-model="form.agrupadora"><option :value="null">SIN AGRUPADORA</option><option v-for="item in agrupadoras" :key="item" :value="item">{{item}}</option></select><small>Sección donde aparecerán los conceptos de este tipo en la boleta.</small></label></div><aside class="preview"><small>VISTA PREVIA</small><p><b>{{form.codigo||'[CÓDIGO]'}}</b><span>{{form.descripcion||'[DESCRIPCIÓN]'}}</span><em v-if="form.agrupadora" class="group" :data-group="form.agrupadora">{{form.agrupadora}}</em></p></aside><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':editing?'Actualizar':'Registrar'}}</button></footer></form></div></div></template>

<style scoped>
.page{--accent:#397d57;color:#35464e}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:20px 23px;display:flex;align-items:center;gap:14px;border-left:5px solid var(--accent);border-radius:12px;background:#fff}.mark{width:48px;height:48px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--accent);font-size:.62rem;font-weight:800}.hero small,.table-card small,.dialog small,.preview small{color:var(--accent);font-size:.48rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7e8a90;font-size:.67rem}.hero strong{margin-left:auto;padding:6px 9px;border-radius:12px;color:var(--accent);background:#eaf6ef;font-size:.52rem}.hero button,.dialog button{padding:9px 12px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.52rem}.flash{padding:9px;border-radius:7px;color:#a64046;background:#fff0f0;font-size:.6rem}.flash.success{color:#287052;background:#edf9f3}.filters{margin-top:10px;padding:13px;display:flex;align-items:end;gap:6px;border-radius:9px;background:#fff}.filters label{min-width:220px;font-size:.52rem}.filters label:first-child{margin-right:auto;width:min(500px,100%)}.filters input,.filters select,.dialog input,.dialog select{width:100%;box-sizing:border-box;margin-top:4px;padding:8px;border:1px solid #d7dfe2;border-radius:6px;background:#fff;font:inherit;font-size:.54rem}.soft{padding:9px 12px;border:0;border-radius:6px;color:#64727a!important;background:#edf1f3!important;font-size:.52rem}.table-card{margin-top:10px;border-radius:10px;background:#fff;overflow:hidden}.table-card>header{padding:13px 15px;border-bottom:1px solid #e7ebed}.table-card h2{margin:2px 0;font-size:.78rem}.scroll{overflow:auto}table{width:100%;min-width:850px;border-collapse:collapse;font-size:.52rem}th,td{padding:9px;border-bottom:1px solid #e8ecee;text-align:left}th{color:#fff;background:#5b6e8e}.active,.inactive,.group{display:inline-block;padding:4px 7px;border-radius:10px;font-size:.42rem;font-style:normal}.active,.group[data-group=REMUNERACIONES]{color:#287154;background:#e6f7ee}.inactive,.group[data-group=DESCUENTOS]{color:#9d4046;background:#fdebed}.group[data-group='APORTACIONES DEL EMPLEADOR']{color:#196b74;background:#e4f5f7}.actions{display:flex;gap:5px}.actions button{padding:6px 8px;border:0;border-radius:5px;font-size:.46rem}.edit{color:#79500b;background:#ffe7bd}.disable{color:#9d4046;background:#fdebed}.enable{color:#287154;background:#e6f7ee}.empty{padding:45px;text-align:center;font-size:.6rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(720px,100%);padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex;align-items:center;gap:9px}.dialog h2{margin:2px 0 12px;font-size:.9rem}.dialog>header>button{margin-left:auto;color:#59666c;background:none;font-size:1.2rem}.dialog label{display:grid;margin-top:8px;font-size:.5rem}.dialog label small{margin-top:5px;color:#7e8a90;font-weight:400}.grid{display:grid;grid-template-columns:1fr 2fr;gap:9px}.span2{grid-column:2}.preview{margin-top:14px;padding:12px;border-radius:7px;background:#f7f8f9}.preview p{margin:6px 0 0;display:flex;align-items:center;gap:9px;font-size:.52rem}.preview span{flex:1}.dialog>footer{margin-top:16px;display:flex;justify-content:flex-end;gap:6px}@media(max-width:760px){.hero,.filters{flex-wrap:wrap}.hero strong{margin-left:0}.filters label{width:100%;min-width:0}.grid{grid-template-columns:1fr}.span2{grid-column:auto}.preview p{align-items:flex-start;flex-direction:column}.actions{min-width:140px}}
</style>
